<script setup lang="ts">
import { computed, onScopeDispose, shallowRef, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useAuthStore } from '../stores/auth'
const auth = useAuthStore()
import { get, mutate } from '../api/client'
import CharacterRelationCanvas from '../components/CharacterRelationCanvas.vue'
import CharacterNetworkInsights from '../components/CharacterNetworkInsights.vue'
import UniverseAnalysisPanel from '../components/UniverseAnalysisPanel.vue'
import RelationEvidenceDetails from '../components/RelationEvidenceDetails.vue'
import CharacterPortrait from '../components/CharacterPortrait.vue'
import EntityNames from '../components/EntityNames.vue'
import { matchesEntityName } from '../utils/entityNames'
import PortraitPreview from '../components/PortraitPreview.vue'
import { providePortraitMode } from '../composables/usePortraitFrames'
import type { CharacterNode,CharacterEdge } from '../types/characterGraph'
import type { CharacterPath } from '../utils/characterAnalysis'
import type { RelationEvidence as Evidence } from '../types/evidence'
interface WorldNetwork {nameNotice?:string;world:{uid:string;title:string;summary:string;seriesUid:string;subjects:{id:number;title:string;order:number;sourceUrl:string}[]};nodes:(CharacterNode&{subjects:number[]})[];edges:(CharacterEdge&{scopeType:string;evidences:Evidence[]})[];truncated:boolean;notice:string;version:string;task:{status:string;processed:number;error:string|null}|null}
const route=useRoute();providePortraitMode()
const data=shallowRef<WorldNetwork>(),error=shallowRef(''),busy=shallowRef(false),pending=shallowRef(false)
const subject=shallowRef(''),relation=shallowRef(''),faction=shallowRef(''),spoilers=shallowRef(false),strict=shallowRef(false),selected=shallowRef<string|null>(null),selectedEdge=shallowRef<string|null>(null),path=shallowRef<CharacterPath|null>(null),search=shallowRef('')
const layout=shallowRef<'network'|'circular'|'roster'>('network'),identities=shallowRef<Record<string,string>[]>([])
let controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,generation=0
const uid=computed(()=>String(route.params.uid)),filter=computed(()=>new URLSearchParams({subjects:subject.value,relation:relation.value,faction:faction.value,spoilers:String(spoilers.value),strict:String(strict.value)}).toString())
const node=computed(()=>data.value?.nodes.find(n=>n.id===selected.value)),edge=computed(()=>data.value?.edges.find(e=>e.id===selectedEdge.value))
const nodes=computed(()=>data.value?.nodes||[]),edges=computed(()=>data.value?.edges||[])
const choices=computed(()=>nodes.value.filter(n=>matchesEntityName(n,search.value)).slice(0,240))
const relationChoices=shallowRef<{code:string;label:string}[]>([]),factions=shallowRef<{id:string;label:string}[]>([])
async function load(){controller?.abort();clearTimeout(timer);const current=new AbortController();controller=current;pending.value=true;error.value='';try{const response=await get<WorldNetwork>(`/universes/${encodeURIComponent(uid.value)}/network?${filter.value}`,current.signal);if(current.signal.aborted)return;data.value=response;if(!relation.value){relationChoices.value=[...new Map(response.edges.map(e=>[e.relationType,{code:e.relationType,label:e.label}])).values()]};if(!faction.value){factions.value=[...new Map(response.edges.filter(e=>e.relationType==='MEMBER'&&e.directed).map(e=>[e.target,{id:e.target,label:response.nodes.find(n=>n.id===e.target)?.label||e.target}])).values()]};if(selected.value&&!response.nodes.some(n=>n.id===selected.value))selected.value=null;if(selectedEdge.value&&!response.edges.some(e=>e.id===selectedEdge.value))selectedEdge.value=null;if(response.task&&['PENDING','RUNNING'].includes(response.task.status))timer=setTimeout(load,2000)}catch(cause){if(!current.signal.aborted)error.value=cause instanceof Error?cause.message:'图谱暂不可用'}finally{if(!current.signal.aborted)pending.value=false}}
async function refresh(){const current=uid.value;busy.value=true;try{await mutate(`/universes/${encodeURIComponent(current)}/jobs`,'POST');if(current===uid.value)await load()}catch(cause){if(current===uid.value)error.value=cause instanceof Error?cause.message:'刷新失败'}finally{if(current===uid.value)busy.value=false}}
watch([uid,filter],()=>{path.value=null;data.value=undefined;selectedEdge.value=null;void load()},{immediate:true})
watch(uid,()=>{generation++;data.value=undefined;selected.value=null;selectedEdge.value=null;subject.value='';relation.value='';faction.value='';relationChoices.value=[];factions.value=[]})
watch(selected,async(id,_old,onCleanup)=>{identities.value=[];const active=new AbortController();onCleanup(()=>active.abort());if(id)try{const rows=await get<Record<string,string>[]>(`/entities/${encodeURIComponent(id)}/identities`,active.signal);if(!active.signal.aborted)identities.value=rows}catch{/* Name/relationship reading remains available without a second source. */}})
function chooseNode(id:string){selected.value=id;selectedEdge.value=null}
function chooseEdge(id:string){selectedEdge.value=id;selected.value=null}
onScopeDispose(()=>{controller?.abort();clearTimeout(timer)})
</script>
<template>
  <RouterLink to="/universes" class="back-link">返回世界观</RouterLink><section class="page-intro"><h1>{{ data?.world.title||'世界观关系' }}</h1><p>{{ data?.world.summary }}</p></section>
  <p v-if="error" class="feedback error" role="alert">{{ error }} <button @click="load">重试</button></p>
  <p v-if="pending" class="feedback" role="status">正在读取当前范围…</p><template v-if="data"><div class="toolbar"><label>作品范围<select v-model="subject"><option value="">全部已收录作品</option><option v-for="work in data.world.subjects" :key="work.id" :value="String(work.id)">{{ work.title }}</option></select></label><label>关系<select v-model="relation"><option value="">全部关系</option><option v-for="r in relationChoices" :key="r.code" :value="r.code">{{ r.label }}</option></select></label><label>组织 / 阵营<select v-model="faction"><option value="">全部角色</option><option v-for="f in factions" :key="f.id" :value="f.id">{{ f.label }}（明确成员证据）</option></select></label><label>布局<select v-model="layout"><option value="network">疏朗网络</option><option value="circular">环形总览</option><option value="roster">角色名册</option></select></label><button v-if="auth.isAdmin" :disabled="busy" @click="refresh">补充世界观样本</button><span v-else class="muted">永久资料补充由管理员在维护模式中执行</span></div><div class="world-options"><label><input v-model="spoilers" type="checkbox">显示已标注剧透</label><label><input v-model="strict" type="checkbox">仅来源明确限定本季的关系</label></div>
  <p class="notice">{{ data.notice }}</p><p v-if="data.task" class="notice" role="status">{{ ({PENDING:'等待补充',RUNNING:'正在补充',PARTIAL:'有界样本已保存',FAILED:'补充失败'} as Record<string,string>)[data.task.status] }} · 已读取 {{ data.task.processed }} 个角色的关系 {{ data.task.error }}</p>
  <p v-if="pending" class="feedback" role="status">正在读取当前范围…</p><p v-if="!nodes.length" class="empty-state">当前范围还没有角色资料。可调整筛选条件；资料补充由管理员核验后执行。</p>
  <p v-if="data.nameNotice" class="feedback" role="status">{{ data.nameNotice }}</p><div v-if="nodes.length" class="world-stage"><CharacterRelationCanvas :nodes="nodes" :edges="edges" :selected-id="selected" :selected-edge-id="selectedEdge" :layout="layout" :reset-key="generation" :show-edge-labels="true" :show-portraits="true" :path="path" @select-node="chooseNode" @select-edge="chooseEdge" @clear-selection="selected=null;selectedEdge=null"/><aside class="world-inspector"><template v-if="node"><CharacterPortrait :node="node" large/><h2>{{ node.label }}</h2><p>{{ node.role }}</p><p>出场范围：{{ node.subjects.map(id=>data?.world.subjects.find(s=>s.id===id)?.title).join('、') }}</p><EntityNames :node="node"/><PortraitPreview :node="node"/><h3>身份核验来源</h3><p v-if="!identities.length">目前没有第二来源映射。</p><p v-for="identity in identities" :key="`${identity.provider}:${identity.provider_id}`"><a :href="identity.source_url" target="_blank" rel="noopener noreferrer">{{ identity.provider }}</a> · {{ identity.status==='REVIEWED'?'人工核验':'候选，未用于实体合并' }}<small>{{ identity.license_label }}</small></p></template><template v-else-if="edge"><h2>{{ edge.label }}</h2><p>{{ nodes.find(n=>n.id===edge?.source)?.label }} {{ edge.directed?'→':'—' }} {{ nodes.find(n=>n.id===edge?.target)?.label }}</p><p>范围：{{ edge.scopeType==='GLOBAL'?'来源全局资料':'来源明确作品范围' }}{{ edge.ended?' · 已结束':'' }}</p><RelationEvidenceDetails v-for="e in edge.evidences" :key="e.uid" :evidence="e"/></template><p v-else>选择角色或关系，核对范围与资料来源。</p><label>查找角色<input v-model="search" placeholder="中文名、原名或已核验别名"></label><button v-for="n in choices" :key="n.id" class="world-node" :aria-pressed="selected===n.id" @click="chooseNode(n.id)">{{ n.label }}</button></aside></div>
  <CharacterNetworkInsights :nodes="nodes" :edges="edges" :selected-id="selected" :truncated="true" @select-node="chooseNode" @select-edge="chooseEdge" @path-change="path=$event"/>
  <UniverseAnalysisPanel @refresh="load" :uid="uid" :filter="filter" :version="data.version"/><details class="panel"><summary>作品成员与来源</summary><p v-for="work in data.world.subjects" :key="work.id"><RouterLink :to="`/explore/anime/${work.id}`">{{ work.title }}</RouterLink> · <a :href="work.sourceUrl" target="_blank" rel="noopener noreferrer">成员依据</a></p><small>样本版本 {{ data.version || '尚未生成' }}；名单范围与关系剧情范围分别核对。</small></details></template>
</template>
<style scoped>.back-link{display:block;margin-top:24px;font-size:13px}.world-options{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0}.world-options label{display:flex;flex-direction:row;align-items:center;gap:8px;font-size:12px}.world-options input{width:16px;height:16px}.world-stage{display:grid;grid-template-columns:minmax(0,1fr) 270px;border:1px solid #dce6d1;border-radius:12px;overflow:hidden}.world-inspector{padding:22px;max-height:750px;overflow:auto;background:#fff;border-left:1px solid #dce6d1;font-size:12px;line-height:1.9;overflow-wrap:anywhere}.world-inspector h2{font-size:20px}.world-inspector h3{font-size:14px}.world-inspector small{display:block;color:#71856f}.world-node{display:block;width:100%;text-align:left;border:0;background:transparent;font-size:12px;padding:10px}.world-node[aria-pressed=true]{background:#edf3e5}.evidence{border-bottom:1px solid #e1e8d9;padding:12px 0}.panel summary{cursor:pointer}@media(max-width:800px){.world-stage{grid-template-columns:1fr}.world-inspector{border-left:0;border-top:1px solid #dce6d1;max-height:420px}}</style>
